const uint lane = thread_index_in_simdgroup;
const uint row0 = (threadgroup_position_in_grid.x * 8 + simdgroup_index_in_threadgroup) * 4;
float acc[4] = {0.f, 0.f, 0.f, 0.f};
for (int k0 = lane * 8; k0 < K; k0 += 256) {
    float xv[8];
    float xs = 0.f;
    for (int i = 0; i < 8; i++) {
        xv[i] = float(x[k0 + i]);
        xs += xv[i];
    }
    const int g = k0 >> 6;
    for (int r = 0; r < 4; r++) {
        uint n = row0 + r;
        if (n >= (uint)N) n = N - 1;  // clamp; result discarded
        uint w = wq[n * (K / 8) + (k0 >> 3)];
        float s = float(scales[n * (K / 64) + g]);
        float b = float(biases[n * (K / 64) + g]);
        float d = 0.f;
        for (int i = 0; i < 8; i++) d += xv[i] * float((w >> (4 * i)) & 0xFu);
        acc[r] += s * d + b * xs;
    }
}
for (int r = 0; r < 4; r++) {
    float t = simd_sum(acc[r]);
    if (lane == 0 && row0 + r < (uint)N) out[row0 + r] = half(t);
}

const uint lane = thread_index_in_simdgroup;
const uint row0 = (threadgroup_position_in_grid.x * 8 + simdgroup_index_in_threadgroup) * 4;
float acc[4] = {0.f, 0.f, 0.f, 0.f};
for (int k0 = lane * 16; k0 < K; k0 += 512) {
    // x pre-scaled by 16^-i so nibbles can be masked in place (no shifts)
    float xp[16];
    float xs = 0.f;
    float sc = 1.f;
    for (int j = 0; j < 2; j++) {
        sc = 1.f;
        for (int i = 0; i < 8; i++) {
            float v = float(x[k0 + j * 8 + i]);
            xs += v;
            xp[j * 8 + i] = v * sc;
            sc *= 0.0625f;
        }
    }
    const int g = k0 >> 6;
    for (int r = 0; r < 4; r++) {
        uint n = row0 + r;
        if (n >= (uint)N) n = N - 1;  // clamp; result discarded
        uint2 w = ld2(wq + n * (K / 8) + (k0 >> 3));
        float s = float(scales[n * (K / 64) + g]);
        float b = float(biases[n * (K / 64) + g]);
        float d = 0.f;
        for (int i = 0; i < 8; i++) {
            d += xp[i] * float(w.x & (0xFu << (4 * i)));
            d += xp[8 + i] * float(w.y & (0xFu << (4 * i)));
        }
        acc[r] += s * d + b * xs;
    }
}
for (int r = 0; r < 4; r++) {
    float t = simd_sum(acc[r]);
    if (lane == 0 && row0 + r < (uint)N) out[row0 + r] = half(t);
}

const uint lane = thread_index_in_simdgroup;
const uint row0 = (threadgroup_position_in_grid.x * 8 + simdgroup_index_in_threadgroup) * 4;
float acc[4] = {0.f, 0.f, 0.f, 0.f};
for (int k0 = lane * 32; k0 < K; k0 += 1024) {
    float xp[32];
    float xs = 0.f;
    for (int j = 0; j < 4; j++) {
        float sc = 1.f;
        for (int i = 0; i < 8; i++) {
            float v = float(x[k0 + j * 8 + i]);
            xs += v;
            xp[j * 8 + i] = v * sc;
            sc *= 0.0625f;
        }
    }
    const int g = k0 >> 6;
    uint4 w[4];
    float s[4], b[4];
    #pragma unroll
    for (int r = 0; r < 4; r++) {
        uint n = row0 + r;
        if (n >= (uint)N) n = N - 1;  // clamp; result discarded
        w[r] = ld4(wq + n * (K / 8) + (k0 >> 3));
        s[r] = float(scales[n * (K / 64) + g]);
        b[r] = float(biases[n * (K / 64) + g]);
    }
    #pragma unroll
    for (int r = 0; r < 4; r++) {
        float d = 0.f;
        for (int i = 0; i < 8; i++) {
            const uint m = 0xFu << (4 * i);
            d += xp[i] * float(w[r].x & m);
            d += xp[8 + i] * float(w[r].y & m);
            d += xp[16 + i] * float(w[r].z & m);
            d += xp[24 + i] * float(w[r].w & m);
        }
        acc[r] += s[r] * d + b[r] * xs;
    }
}
for (int r = 0; r < 4; r++) {
    float t = simd_sum(acc[r]);
    if (lane == 0 && row0 + r < (uint)N) out[row0 + r] = half(t);
}

const uint lane = thread_index_in_simdgroup;
const uint row0 = (threadgroup_position_in_grid.x * 8 + simdgroup_index_in_threadgroup) * 4;
float acc[4] = {0.f, 0.f, 0.f, 0.f};
uint nr[4];
for (int r = 0; r < 4; r++) {
    uint n = row0 + r;
    nr[r] = n >= (uint)N ? (uint)(N - 1) : n;  // clamp; result discarded
}
int k0 = lane * 16;
uint2 w[4];
float s[4], b[4];
if (k0 < K) {
    #pragma unroll
    for (int r = 0; r < 4; r++) {
        w[r] = ld2(wq + nr[r] * (K / 8) + (k0 >> 3));
        s[r] = float(scales[nr[r] * (K / 64) + (k0 >> 6)]);
        b[r] = float(biases[nr[r] * (K / 64) + (k0 >> 6)]);
    }
}
for (; k0 < K; k0 += 512) {
    // prefetch next iteration (reload current if past the end; harmless)
    int kn = k0 + 512;
    if (kn >= K) kn = k0;
    uint2 wn[4];
    float sn[4], bn[4];
    #pragma unroll
    for (int r = 0; r < 4; r++) {
        wn[r] = ld2(wq + nr[r] * (K / 8) + (kn >> 3));
        sn[r] = float(scales[nr[r] * (K / 64) + (kn >> 6)]);
        bn[r] = float(biases[nr[r] * (K / 64) + (kn >> 6)]);
    }
    float xp[16];
    float xs = 0.f;
    for (int j = 0; j < 2; j++) {
        float sc = 1.f;
        for (int i = 0; i < 8; i++) {
            float v = float(x[k0 + j * 8 + i]);
            xs += v;
            xp[j * 8 + i] = v * sc;
            sc *= 0.0625f;
        }
    }
    #pragma unroll
    for (int r = 0; r < 4; r++) {
        float d = 0.f;
        for (int i = 0; i < 8; i++) {
            const uint m = 0xFu << (4 * i);
            d += xp[i] * float(w[r].x & m);
            d += xp[8 + i] * float(w[r].y & m);
        }
        acc[r] += s[r] * d + b[r] * xs;
    }
    #pragma unroll
    for (int r = 0; r < 4; r++) { w[r] = wn[r]; s[r] = sn[r]; b[r] = bn[r]; }
}
for (int r = 0; r < 4; r++) {
    float t = simd_sum(acc[r]);
    if (lane == 0 && row0 + r < (uint)N) out[row0 + r] = half(t);
}
